      "to_stock": null,
      "position": {
        "x": 550,
        "y": 50
      }
    },
    {
      "id": "flow-thruput",
      "name": "Throughput",
      "equation": "Flow_Rate",
      "from_stock": null,
      "to_stock": "stock-throughput",
      "position": {
        "x": 300,
        "y": 175
      }
    }
  ],
  "variables": [
    {
      "id": "var-demand",
      "name": "Demand",
