      "position": {
        "x": 100,
        "y": 50
      }
    },
    {
      "id": "var-peakfact",
      "name": "Peak_Factor",
      "equation": "0.4",
      "position": {
        "x": 200,
        "y": 50
      }
    },
    {
      "id": "var-critdens",
      "name": "Critical_Density",
      "equation": "50",
      "position": {
        "x": 400,
        "y": 175
      }
    },
    {
      "id": "var-jamdens",
      "name": "Jam_Density",
      "equation": "150",
      "position": {
        "x": 500,
        "y": 175
      }
    },
    {
      "id": "var-freeflow",
      "name": "Free_Flow_Speed",
      "equation": "60",
